CLIENT_TYPES = ("app", "web")


def bridge_existing_users(apps, schema_editor):
    """给每个已有账号按历史 ``session_version`` 补 ``app`` + ``web`` 两行端会话。

    两行取**同一个值**:老令牌按 ``app`` 兜底,而 ``web`` 与 ``app`` 同值意味着升级后
    网页端的老 refresh 也不会立刻失效(它们同样没有 ``ct``)。之后再登录才各自递增。

    Args:
        apps: 迁移期间的应用注册表。
        schema_editor: 当前数据库的 schema 编辑器(未使用)。
    """
    User = apps.get_model("accounts", "User")
    DeviceSession = apps.get_model("accounts", "DeviceSession")
    rows = [
        DeviceSession(user_id=user.id, client_type=client_type,
                      version=user.session_version)
        for user in User.objects.all().iterator()
        for client_type in CLIENT_TYPES
    ]
    DeviceSession.objects.bulk_create(rows, ignore_conflicts=True, batch_size=1000)


